CREATE OR REPLACE FUNCTION public.get_public_home_design() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('design',CASE WHEN value->>'design' IN ('current','premium-map') THEN value->>'design' ELSE 'current' END,'previous',CASE WHEN value->>'previous' IN ('current','premium-map') THEN value->>'previous' ELSE 'current' END) FROM (SELECT (SELECT value FROM public.app_settings WHERE key='public_home_design') value) s; $$;
CREATE OR REPLACE FUNCTION public.save_public_home_design(_design text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old_design text; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Apenas administradores podem alterar o design'; END IF; IF _design NOT IN ('current','premium-map') OR _design IS NULL THEN RAISE EXCEPTION 'Design inválido'; END IF; PERFORM pg_advisory_xact_lock(hashtext('public_home_design')); SELECT COALESCE(value->>'design','current') INTO old_design FROM public.app_settings WHERE key='public_home_design'; old_design:=COALESCE(old_design,'current'); IF old_design<>_design THEN INSERT INTO public.app_settings(key,value,updated_at) VALUES('public_home_design',jsonb_build_object('design',_design,'previous',old_design),now()) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at; END IF; RETURN public.get_public_home_design(); END $$;
REVOKE ALL ON FUNCTION public.get_public_home_design(),public.save_public_home_design(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_public_home_design() TO anon,authenticated;
GRANT EXECUTE ON FUNCTION public.save_public_home_design(text) TO authenticated;
